<?php $page_title='Notifications'; require_once 'includes/header.php'; require_login();$uid=(int)user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$uid]);flash('success','Notifications marked as read.');redirect('notifications.php');}$s=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 50');$s->execute([$uid]);$notes=$s->fetchAll();$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$uid]);?>
<section class="page-hero"><span class="kicker">YOUR UPDATES</span><h1>Notifications.</h1><p>Stay on top of requests, approvals and community activity.</p></section><div class="form-card" style="max-width:900px;margin-bottom:80px"><?php foreach($notes as $n): ?><div class="notification-item"><div class="notification-dot"></div><div><b><?=e($n['title'])?></b><p><?=e($n['message'])?></p><small><?=e(time_ago($n['created_at']))?></small><?php if($n['link']):?> · <a class="text-link" href="<?=e($n['link'])?>">Open</a><?php endif;?></div></div><?php endforeach;if(!$notes):?><div class="empty-state"><h3>No notifications yet</h3><p>When someone interacts with your food or requests, updates will appear here.</p></div><?php endif;?></div><?php require_once 'includes/footer.php'; ?>
